568	\begin{fact}\label{fact:add-a-proj}
569	Let $\{A_a^{x}\}$ and $\{B_a^{x}\}$ be matrices.
570	Let $\{C_b^{y}\}$ be matrices such that $\sum_b (C_b^y)^\dagger C_b^y \leq I$ for all~$y$.
571	(This includes the case when $\{C_b^y\}$ form projective or POVM measurements.) Then
572	\begin{equation*}
573	\text{$A_a^{x} \approx_{\delta} B_a^x$ implies $C_b^y A_a^x \approx_{\delta} C_b^y B_a^x$.}
574	\end{equation*}
575	\end{fact}
576	\begin{proof}
577	Fix questions~$x, y$ and answers~$a$. Because of our property on $\{C_b^y\}_b$,
578	\begin{align*}
579	\sum_{b} \Vert (C_b^{y} A_a^{x} - C_b^{y} B_a^{x})\ket{\psi}\Vert^2
580	&= \sum_{b} \bra{\psi} (A_a^x - B_a^x)^\dagger (C_b^y)^\dagger (C_b^y) (A_a^{x} -  B_a^{x})\ket{\psi}\\
581	&\leq \bra{\psi} (A_a^x - B_a^x)^\dagger (A_a^x - B_a^x) \ket{\psi}
582	 = \Vert (A_a^{x} -B_a^{x})\ket{\psi}\Vert^2
583	\end{align*}
584	We can therefore derive our desired conclusion:
585	\begin{equation*}
586	\E_{\bx, \by} \sum_{a, b} \Vert (C_b^{\by} A_a^{\bx} - C_b^{\by} B_a^{\bx}) \ket{\psi} \Vert^2
587	\leq \E_{\bx, \by} \sum_{a} \Vert (A_a^{\bx} - B_a^{\bx}) \ket{\psi} \Vert^2
588	= \delta.\qedhere
589	\end{equation*}
590	\end{proof}
